authored-nesting.source:
@startmindmap
<style>
/* block comment */
mindmapDiagram {
  --accent: #ABCDEF;
  node {
    Padding 12
    :depth(1) {
      BackGroundColor var(--accent)
      leafNode {
        FontColor red
        LineColor "#123456"
      }
    }
  }
  .hot, .cold {
    BackGroundColor pink
  }
  boxless * {
    FontSize 18
  }
  arrow, rootNode {
    LineThickness 3.0; LineStyle 4-2
  }
  :depth(2) * {
    FontStyle bold
  }
}
// line comment
@media (prefers-color-scheme:dark) {
  mindmapDiagram {
    node { BackGroundColor black }
  }
}
</style>
* r
** a <<hot>>
*** b
@endmindmap

